class BasePage:
    def __init__(self, driver):
        self.driver = driver
        self.wait = WebDriverWait(driver, 10)
    def find(self, locator):
        return self.wait.until(EC.presence_of_element_located(locator))
print('BasePage provides find with wait')

class SearchPage:
    def __init__(self, driver):
        self.driver = driver
    def enter_query(self, text):
        self.driver.find_element(By.NAME, 'q').send_keys(text)
        return self
    def click_search(self):
        self.driver.find_element(By.NAME, 'btnK').click()
        return self
print('Fluent interface pattern')

class ProfilePage:
    def __init__(self, driver):
        self.driver = driver
    @property
    def name_field(self):
        return self.driver.find_element(By.ID, 'name')
    @property
    def email_field(self):
        return self.driver.find_element(By.ID, 'email')
print('Property-based lazy lookup')

