import allure

@allure.step('Enter credentials: {username}')
def enter_credentials(driver, username, password):
    driver.find_element(By.ID, 'user').send_keys(username)
    driver.find_element(By.ID, 'pass').send_keys(password)
print('Allure step defined')

@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item, call):
    outcome = yield
    report = outcome.get_result()
    if report.when == 'call' and report.failed:
        driver = item.funcargs.get('driver')
        if driver:
            img = driver.get_screenshot_as_base64()
            extra = [{'name': 'Screenshot', 'content': img, 'mime_type': 'image/png'}]
print('Failure screenshot hook defined')

